class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (int r = 1; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int best = matrix[r - 1][c];
                if (c > 0) best = min(best, matrix[r - 1][c - 1]);
                if (c + 1 < n) best = min(best, matrix[r - 1][c + 1]);
                matrix[r][c] += best;
            }
        }
        return *min_element(matrix[n - 1].begin(), matrix[n - 1].end());
    }
};
